local Players=game:GetService('Players')
local UIS=game:GetService('UserInputService')
local PG=Players.LocalPlayer:WaitForChild('PlayerGui')
local env=getgenv and getgenv() or _G
if env.KoreanChainCleanup then pcall(env.KoreanChainCleanup) end
local Rayfield=loadstring(game:HttpGet('https://sirius.menu/rayfield'))()
local Window=Rayfield:CreateWindow({Name='KoreanHub · 한국 끝말잇기',LoadingTitle='끝말잇기 사전',LoadingSubtitle='첨부 사전 56,301개 항목',ConfigurationSaving={Enabled=false},KeySystem=false})
local Tab=Window:CreateTab('끝말잇기',4483362458)
local alive,auto,submit,speed=true,false,false,10
local target,source,selectSource,captureInput=nil,nil,false,false
local seen,connections={},{}
local seed,lastAuto,busy,generation='',nil,false,0
local suggestions={}
local detect=true
local detectedChar=nil
local labels={}
local custom={}
local customFile='KoreanHub_WordChain_Custom.json'
local status=Tab:CreateParagraph({Title='상태',Content='입력창을 먼저 지정하세요.'})
local preview=Tab:CreateParagraph({Title='추천 단어',Content='마지막 단어나 시작 글자를 입력하세요.'})
local function tell(s) status:Set({Title='상태',Content=s}) end
local function visible(o)
 if not o or not o:IsDescendantOf(PG) then return false end
 local p=o
 while p and p~=PG do
  if p:IsA('GuiObject') and not p.Visible then return false end
  if p:IsA('ScreenGui') and not p.Enabled then return false end
  p=p.Parent
 end
 return true
end
local function normalize(s) return (s:gsub('<[^>]->',''):gsub('%s+','')) end
local function tail(s)
 local last
 for _,cp in utf8.codes(s) do if cp>=0xAC00 and cp<=0xD7A3 then last=utf8.char(cp) end end
 return last
end
local function promptChar(text)
 local clean=normalize(text)
 local before=clean:match('^(.-)시작하는단어')
 if not before then return nil end
 before=before:gsub('으로$',''):gsub('로$','')
 -- Quotes may occur between the syllable and the particle.
 local chars={}
 for _,cp in utf8.codes(before) do
  if cp>=0xAC00 and cp<=0xD7A3 then chars[#chars+1]=utf8.char(cp) end
 end
 if #chars~=1 then return nil end
 return chars[1]
end
local function gameVisible(o)
 if not o or not o.Parent then return false end
 local p=o
 while p and p~=game do
  if p:IsA('GuiObject') and not p.Visible then return false end
  if p:IsA('LayerCollector') and not p.Enabled then return false end
  p=p.Parent
 end
 return true
end
local function trackLabel(o)
 if o:IsA('TextLabel') or o:IsA('TextButton') then labels[o]=true end
end
for _,o in ipairs(PG:GetDescendants()) do trackLabel(o) end
connections[#connections+1]=PG.DescendantAdded:Connect(trackLabel)
task.spawn(function()
 local n=0
 for _,o in ipairs(workspace:GetDescendants()) do
  if (o:IsA('TextLabel') or o:IsA('TextButton')) and (o:FindFirstAncestorOfClass('BillboardGui') or o:FindFirstAncestorOfClass('SurfaceGui')) then trackLabel(o) end
  n=n+1;if n%500==0 then task.wait() end
 end
end)
connections[#connections+1]=workspace.DescendantAdded:Connect(function(o)
 if (o:IsA('TextLabel') or o:IsA('TextButton')) and (o:FindFirstAncestorOfClass('BillboardGui') or o:FindFirstAncestorOfClass('SurfaceGui')) then trackLabel(o) end
end)
local function addWord(w)
 w=normalize(w)
 local ok,len=pcall(utf8.len,w)
 if not ok or not len or len<2 or len>100 then return false end
 local first=utf8.offset(w,2);local key=w:sub(1,first-1)
 local cp=utf8.codepoint(key);if cp<0xAC00 or cp>0xD7A3 then return false end
 DICT[key]=DICT[key] or {}
 if not table.find(DICT[key],w) then table.insert(DICT[key],1,w) end
 custom[w]=true
 return true
end
local function saveWords()
 if type(writefile)~='function' then return false end
 local words={};for w in pairs(custom) do words[#words+1]=w end;table.sort(words)
 return pcall(function() writefile(customFile,game:GetService('HttpService'):JSONEncode(words)) end)
end
if type(readfile)=='function' then
 pcall(function()
  local words=game:GetService('HttpService'):JSONDecode(readfile(customFile))
  if type(words)=='table' then for _,w in ipairs(words) do if type(w)=='string' then addWord(w) end end end
 end)
end
local function starts(ch)
 local a={ch};local cp=utf8.codepoint(ch);local n=cp-0xAC00
 if n>=0 and n<11172 then
  local l=math.floor(n/588);local v=math.floor(n%588/28);local t=n%28
  if l==5 then local nextL=({[2]=11,[6]=11,[7]=11,[12]=11,[17]=11,[20]=11})[v] or 2;a[#a+1]=utf8.char(0xAC00+nextL*588+v*28+t)
  elseif l==2 and (v==6 or v==12 or v==17 or v==20) then a[#a+1]=utf8.char(0xAC00+11*588+v*28+t) end
 end
 return a
end
local function refresh()
 suggestions={};local ch=detectedChar or promptChar(seed) or tail(normalize(seed));local dedup={}
 if ch then
  for _,s in ipairs(starts(ch)) do
   for _,w in ipairs(DICT[s] or {}) do
    if not seen[w] and not dedup[w] then suggestions[#suggestions+1]=w;dedup[w]=true end
   end
  end
 end
 local list={}
 for i=1,math.min(10,#suggestions) do list[#list+1]=i..'. '..suggestions[i] end
 preview:Set({Title='추천 · '..(ch or '미지정')..' · '..#suggestions..'개',Content=#list>0 and table.concat(list,'\n') or '사용 가능한 후보가 없습니다.'})
end
local function cancel() generation=generation+1 end
local function typeWord()
 if busy then return end
 if not visible(target) or not target:IsA('TextBox') then tell('지정한 게임 입력창이 보이지 않습니다.');return end
 if UIS:GetFocusedTextBox()~=target then tell('게임 입력창을 터치해 활성화하세요.');return end
 refresh();local w=suggestions[1]
 if not w then tell('후보 없음');return end
 if target.Text~='' then tell('입력창을 비운 뒤 다시 시도하세요.');return end
 busy=true;local ticket=generation
 task.spawn(function()
  local ok,err=pcall(function()
   local offsets={}
   for pos in utf8.codes(w) do offsets[#offsets+1]=pos end
   offsets[#offsets+1]=#w+1
   for i=1,#offsets-1 do
    if not alive or ticket~=generation or not visible(target) or UIS:GetFocusedTextBox()~=target then return end
    target.Text=w:sub(1,offsets[i+1]-1)
    task.wait(1/speed)
   end
   if ticket~=generation then return end
   if submit then
    target:ReleaseFocus(true)
    seen[w]=true
    tell('제출 시도: '..w..' · 게임의 승인 여부는 확인되지 않음')
   else tell('입력 완료: '..w..' · 게임의 확인 버튼으로 제출하세요.') end
  end)
  busy=false
  if not ok then tell('입력 오류: '..tostring(err)) end
 end)
end
Tab:CreateInput({Name='상대 단어 또는 시작 글자',PlaceholderText='예: 사과 또는 과',RemoveTextAfterFocusLost=false,Callback=function(v) detectedChar=nil;seed=v;lastAuto=nil;refresh() end})
Tab:CreateButton({Name='게임 입력창 지정 · 누른 뒤 게임 입력칸 터치',Callback=function() captureInput=true;tell('다음에 터치하는 게임 입력창을 기억합니다.') end})
connections[#connections+1]=UIS.TextBoxFocused:Connect(function(box)
 if captureInput then captureInput=false;target=box;cancel();tell('입력창 지정: '..box:GetFullName()) end
end)
Tab:CreateButton({Name='상대 단어 표시 지정 · 누른 뒤 해당 글자 터치',Callback=function() selectSource=true;tell('0.5초 뒤 상대 단어가 표시된 글자를 터치하세요.') end})
connections[#connections+1]=UIS.InputBegan:Connect(function(input)
 if not selectSource then return end
 if input.UserInputType~=Enum.UserInputType.Touch and input.UserInputType~=Enum.UserInputType.MouseButton1 then return end
 local pos=input.Position
 for _,o in ipairs(PG:GetGuiObjectsAtPosition(pos.X,pos.Y)) do
  if (o:IsA('TextLabel') or o:IsA('TextButton')) then
   local root=o:FindFirstAncestorOfClass('ScreenGui')
   if root and not root.Name:lower():find('rayfield') then
    source=o;selectSource=false;seed=o.Text;lastAuto=nil;refresh();tell('상대 단어 표시 지정: '..o:GetFullName());break
   end
  end
 end
end)
Tab:CreateToggle({Name='시작 글자 자동 감지',CurrentValue=true,Flag='ChainDetect',Callback=function(v) detect=v;detectedChar=nil;lastAuto=nil;refresh() end})
Tab:CreateInput({Name='단어 추가 · 쉼표나 줄바꿈으로 여러 개',PlaceholderText='예: 중학교, 중력',RemoveTextAfterFocusLost=true,Callback=function(v)
 local count=0
 for w in v:gmatch('[^,\n\r]+') do if addWord(w) then count=count+1 end end
 local saved=saveWords();refresh();lastAuto=nil
 tell(count..'개 단어 등록 · '..(saved and '저장 완료' or '이번 실행에만 유지'))
end})
Tab:CreateSlider({Name='타자 속도 · 초당 글자 수',Range={1,1000},Increment=1,CurrentValue=10,Flag='ChainSpeed',Callback=function(v) speed=math.clamp(tonumber(v) or 10,1,1000) end})
Tab:CreateToggle({Name='자동입력 · 지정 입력창이 활성화된 동안',CurrentValue=false,Flag='ChainAuto',Callback=function(v) auto=v;cancel();lastAuto=nil end})
Tab:CreateToggle({Name='입력 후 Enter 제출 시도',CurrentValue=false,Flag='ChainSubmit',Callback=function(v) submit=v end})
Tab:CreateButton({Name='첫 번째 추천 단어 입력',Callback=typeWord})
Tab:CreateButton({Name='현재 입력한 단어를 사용됨으로 기록',Callback=function()
 if target then local w=normalize(target.Text);if w~='' then seen[w]=true;refresh();tell('사용 기록: '..w) end end
end})
Tab:CreateInput({Name='사용되었거나 거절된 단어 제외',PlaceholderText='단어 입력',RemoveTextAfterFocusLost=true,Callback=function(v) v=normalize(v);if v~='' then seen[v]=true;refresh() end end})
Tab:CreateButton({Name='새 게임 · 사용 기록 초기화',Callback=function() cancel();seen={};lastAuto=nil;refresh();tell('사용 기록 초기화') end})
Tab:CreateParagraph({Title='사용 방법 / 적용 범위',Content='‘중’으로 시작하는 단어 형태의 안내를 자동 감지합니다. 입력칸 자동 선택이 맞지 않으면 직접 지정하세요. 자동입력은 지정 입력창을 직접 터치했을 때만 동작하며 차례를 자동 판별하지 않습니다. 같은 표시에는 한 번만 입력합니다. Enter 제출은 게임별로 다르며 기본은 꺼짐입니다. 속도 1000은 프레임 속도에 제한됩니다. 사전 순서를 유지하며 모든 단어의 게임 허용 여부는 미검증입니다.'})
 task.spawn(function()
 while alive do
  task.wait(0.15)
  local found,chosen=nil,nil
  if detect then
   for o in pairs(labels) do
    if not o.Parent then labels[o]=nil
    elseif gameVisible(o) then
     local ch=promptChar(o.Text)
     if ch then
      if found and found~=ch then found=nil;chosen=nil;break end
      found=ch;chosen=o
     end
    end
   end
   if found~=detectedChar then
    cancel();detectedChar=found;lastAuto=nil
    if found then seed=found;tell('시작 글자 감지: '..found) else seed='';tell('시작 안내 대기 · 입력창을 못 찾으면 직접 지정하세요.') end
    refresh()
   end
   if found and not visible(target) then
    local best,score=nil,-math.huge
    local camera=workspace.CurrentCamera
    if camera then
     local vp=camera.ViewportSize
     for _,box in ipairs(PG:GetDescendants()) do
      if box:IsA('TextBox') and visible(box) and box.TextEditable then
       local pos=box.AbsolutePosition+box.AbsoluteSize/2
       local root=box:FindFirstAncestorOfClass('ScreenGui')
       local path=box:GetFullName():lower()
       if root and not path:find('chat') and not root.Name:lower():find('rayfield') then
        local area=box.AbsoluteSize.X*box.AbsoluteSize.Y
        local q=area-(pos-vp/2).Magnitude*100
        if q>score then best=box;score=q end
       end
      end
     end
    end
    if best then target=best;tell('시작 글자: '..found..' · 입력칸을 터치하면 자동입력') end
   end
  elseif source and visible(source) and seed~=source.Text then cancel();seed=source.Text;refresh() end
  if auto and not busy and visible(target) and UIS:GetFocusedTextBox()==target and target.Text=='' and tail(seed) and seed~=lastAuto then
   lastAuto=seed;typeWord()
  end
 end
end)
env.KoreanChainCleanup=function()
 alive=false;auto=false;cancel()
 for _,c in ipairs(connections) do c:Disconnect() end
 pcall(function() Rayfield:Destroy() end)
end
